import java.util.function.Function;
import java.util.function.Supplier;
import lombok.val;
import lombok.var;

class T2 {
    static <T> T id(T x) { return x; }
    interface ThrowSupplier<T> { T apply() throws Throwable; }
    static <T> T ass(ThrowSupplier<T> s) { try { return s.apply(); } catch (Throwable t) { throw new RuntimeException(t); } }

    public void nested() {
        val a = id(() -> {
            val b = id(() -> {
                val c = "deep";
                return c;
            });
            return b;
        });
        System.out.println(a);
    }

    public void withVar() {
        var v = id(() -> {
            var w = "x";
            return w;
        });
        System.out.println(v);
    }

    public void anon() {
        val s = ass(new ThrowSupplier<String>() {
            public String apply() {
                val inner = "anon";
                return inner;
            }
        });
        System.out.println(s);
    }

    public void multipleNested() {
        val r = id(() -> {
            val p = id(() -> "p");
            val q = id(() -> "q");
            return p + q;
        });
        System.out.println(r);
    }

    public void cascade() {
        val cipher = ass(() -> { val x = "C"; return x; });
        val u = cipher.toUpperCase();
        val v2 = u.trim();
        System.out.println(v2);
    }

    Runnable loopInsideLambda = () -> {
        for (val z : new int[]{1,2}) {
            System.out.println(z);
        }
    };
}
